function telegramMarkdownText(string $value): string
{
    $backslash = '\\';
    $special = str_split('_*[]()~`>#+-=|{}.!');
    $special[] = $backslash;
    $replacements = [];

    foreach ($special as $character) {
        $replacements[$character] = $backslash.$character;
    }

    return strtr($value, $replacements);
}

